import { useState, useEffect } from "react";
import { adminGetKycList } from "./kycApi";
import { kycRequests as mockData } from "../data/mockData";

// ─────────────────────────────────────────────────────────────────
// Custom hook: fetch KYC list from real API,
// fall back to mock data if API is unreachable
// ─────────────────────────────────────────────────────────────────
export function useKycData() {
  const [data, setData]       = useState(mockData);   // start with mock
  const [loading, setLoading] = useState(true);
  const [error, setError]     = useState(null);
  const [usingMock, setUsingMock] = useState(false);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);

    adminGetKycList()
      .then((res) => {
        if (cancelled) return;
        // Map backend fields → portal fields if needed
        const mapped = res.data?.users || res.data?.kyc || res.data || mockData;
        setData(Array.isArray(mapped) ? mapped : mockData);
        setUsingMock(false);
      })
      .catch(() => {
        if (cancelled) return;
        // Backend not running or no admin endpoint yet → use mock
        setData(mockData);
        setUsingMock(true);
        setError("Using demo data — backend not reachable");
      })
      .finally(() => { if (!cancelled) setLoading(false); });

    return () => { cancelled = true; };
  }, []);

  return { data, setData, loading, error, usingMock };
}
